from pysat.solvers import Glucose3
from pysat.card import CardEnc

n = 27

# Fixed assignments
fixed = {9: 23, 12: 13, 18: 1, 21: 21, 26: 14}

# We'll create variables: x[i][j] = i*n + j + 1 (1-indexed for pysat)
def var(i, j):
    return i * n + j + 1

solver = Glucose3()

# Each row has exactly one queen
for i in range(n):
    clause = [var(i, j) for j in range(n)]
    solver.add_clause(clause)
    # At most one per row
    for j1 in range(n):
        for j2 in range(j1+1, n):
            solver.add_clause([-var(i, j1), -var(i, j2)])

# Each column has at most one queen
for j in range(n):
    for i1 in range(n):
        for i2 in range(i1+1, n):
            solver.add_clause([-var(i1, j), -var(i2, j)])

# Diagonals (top-left to bottom-right): i - j = constant
for d in range(-(n-1), n):
    cells = [(i, j) for i in range(n) for j in range(n) if i - j == d]
    for idx1 in range(len(cells)):
        for idx2 in range(idx1+1, len(cells)):
            i1, j1 = cells[idx1]
            i2, j2 = cells[idx2]
            solver.add_clause([-var(i1, j1), -var(i2, j2)])

# Diagonals (top-right to bottom-left): i + j = constant
for s in range(0, 2*(n-1)+1):
    cells = [(i, j) for i in range(n) for j in range(n) if i + j == s]
    for idx1 in range(len(cells)):
        for idx2 in range(idx1+1, len(cells)):
            i1, j1 = cells[idx1]
            i2, j2 = cells[idx2]
            solver.add_clause([-var(i1, j1), -var(i2, j2)])

# Fixed assignments
for i, j in fixed.items():
    solver.add_clause([var(i, j)])

result = solver.solve()
print("SAT" if result else "UNSAT")

if result:
    model = solver.get_model()
    solution = [None] * n
    for i in range(n):
        for j in range(n):
            if model[var(i, j)-1] > 0:
                solution[i] = j
    print(solution)
    # Verify
    # Check rows
    assert len(set(solution)) == n
    # Check columns
    assert len(set(solution)) == n
    # Check diagonals
    for i1 in range(n):
        for i2 in range(i1+1, n):
            j1, j2 = solution[i1], solution[i2]
            assert abs(i1-i2) != abs(j1-j2), f"Conflict between ({i1},{j1}) and ({i2},{j2})"
    print("Verified!")
